-- Cloverleaf results present on MileSplit but missing from meets the DB already has (BRAIN.md [C74]). Inserts only; never touches an existing row.
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @p INT;
IF (SELECT COUNT(*) FROM Athletes WHERE (Id = 133 AND FirstName = 'Dillon' AND LastName = 'West') OR (Id = 558 AND FirstName = 'Asa' AND LastName = 'Gynn') OR (Id = 642 AND FirstName = 'Tristan' AND LastName = 'Vaughan') OR (Id = 689 AND FirstName = 'Max' AND LastName = 'Gucker')) <> 4 THROW 50010, 'Athlete Ids do not match this database', 1;
IF (SELECT COUNT(*) FROM Meets WHERE (Name = '2018 Oberlin College Grand Prix Series #3' AND Date = '2018-02-03') OR (Name = '2020 Oberlin College High School Meet #1' AND Date = '2020-01-11') OR (Name = '2019 Nikki Reynolds Invitational' AND Date = '2019-04-27') OR (Name = '2021 Tom Fasko Medina Relays' AND Date = '2021-04-10') OR (Name = '2021 Nikki Reynolds Invitational' AND Date = '2021-05-01') OR (Name = '2018 Western Reserve Relays' AND Date = '2018-04-26') OR (Name = '2018 Nikki Reynolds Invitational' AND Date = '2018-04-28')) <> 7 THROW 50011, 'Meet Ids do not match this database', 1;
IF (SELECT COUNT(*) FROM Events WHERE (Id = 10 AND Name = 'Seated Shot Put' AND Gender = 2) OR (Id = 12 AND Name = 'Shot Put' AND Gender = 2) OR (Id = 33 AND Name = 'Seated 200M' AND Gender = 2) OR (Id = 47 AND Name = 'Seated 100M' AND Gender = 2) OR (Id = 51 AND Name = 'Seated 400M' AND Gender = 2) OR (Id = 67 AND Name = 'Seated 800M' AND Gender = 2) OR (Id = 112 AND Name = '4x800M Relay' AND Gender = 2)) <> 7 THROW 50012, 'Event Ids do not match this database', 1;
-- 2020 Oberlin College High School Meet #1: Shot Put Megan Van Meter 289.5
IF NOT EXISTS (SELECT 1 FROM Performances WHERE MeetId = (SELECT Id FROM Meets WHERE Name = '2020 Oberlin College High School Meet #1' AND Date = '2020-01-11') AND EventId = 12 AND AthleteId = (SELECT Id FROM Athletes WHERE FirstName = 'Megan' AND LastName = 'Van Meter' AND Gender = 2))
    INSERT INTO Performances (AthleteId, MeetId, EventId, DistanceInches, TimeSeconds, SchoolRecord, SeasonBest, PersonalBest, ResultStatus) VALUES ((SELECT Id FROM Athletes WHERE FirstName = 'Megan' AND LastName = 'Van Meter' AND Gender = 2), (SELECT Id FROM Meets WHERE Name = '2020 Oberlin College High School Meet #1' AND Date = '2020-01-11'), 12, 289.5, NULL, 0, 0, 0, 0);
-- 2018 Oberlin College Grand Prix Series #3: 4x800M Relay Tristan Vaughan, Dillon West, Max Gucker, Asa Gynn 562.38
IF NOT EXISTS (SELECT 1 FROM Performances WHERE MeetId = (SELECT Id FROM Meets WHERE Name = '2018 Oberlin College Grand Prix Series #3' AND Date = '2018-02-03') AND EventId = 112 AND AthleteId IS NULL AND ABS(ISNULL(TimeSeconds, 0) + ISNULL(DistanceInches, 0) - 562.38) < 0.06)   -- a school can enter several relay teams in one event
BEGIN
    INSERT INTO Performances (AthleteId, MeetId, EventId, DistanceInches, TimeSeconds, SchoolRecord, SeasonBest, PersonalBest, ResultStatus) VALUES (NULL, (SELECT Id FROM Meets WHERE Name = '2018 Oberlin College Grand Prix Series #3' AND Date = '2018-02-03'), 112, NULL, 562.38, 0, 0, 0, 0);
    SET @p = SCOPE_IDENTITY();
    INSERT INTO PerformanceAthletes (PerformanceId, AthleteId) VALUES (@p, 642);
    INSERT INTO PerformanceAthletes (PerformanceId, AthleteId) VALUES (@p, 133);
    INSERT INTO PerformanceAthletes (PerformanceId, AthleteId) VALUES (@p, 689);
    INSERT INTO PerformanceAthletes (PerformanceId, AthleteId) VALUES (@p, 558);
END
